fn frame(t: i32) {
    host::display::clear(0x0e0e12);
    let own: i32 = host::agent::viewer_is_owner();
    let count: i32 = host::agent::subscriber_count();

    if own == 1 {
        host::display::fill_rect(0, 0, 512, 50, 0x5c1a1a);
        host::display::draw_string(20, 16, "OWNER CONSOLE", 0xffffff, 2);
        host::display::fill_rect(96, 180, 320, 90, 0xdddddd);
        host::display::draw_string(140, 212, "PING SUBSCRIBERS", 0x000000, 2);
        host::display::draw_string(96, 320, "THIS BUTTON ONLY RENDERS FOR", 0x777777, 1);
        host::display::draw_string(96, 336, "THE DEVICE THAT OWNS THE NAME", 0x777777, 1);
        let flash: i32 = host::display::state_get(1);
        if flash > 0 {
            host::display::draw_string(200, 300, "SENT", 0x22bb44, 2);
            host::display::state_set(1, flash - 1);
        }
        let down: i32 = host::display::pointer_down();
        let prev: i32 = host::display::state_get(0);
        host::display::state_set(0, down);
        if down == 1 && prev == 0 {
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            if px >= 96 && px < 416 && py >= 180 && py < 270 {
                host::agent::broadcast("Owner ping", "The owner waved at the feed.");
                host::display::state_set(1, 40);
            }
        }
    } else {
        host::display::fill_rect(0, 0, 512, 50, 0x1a2430);
        host::display::draw_string(20, 16, "VISITOR VIEW", 0x8899aa, 2);
        host::display::draw_string(96, 220, "ADMIN TOOLS ARE HIDDEN", 0x666677, 2);
    }
    host::display::draw_string(20, 470, "SUBSCRIBERS", 0x556677, 1);
    host::display::draw_number(120, 466, count, 0xffffff, 2);
    host::display::present();
}
